configuration.config:
type Loaders is ("RAM", "USER");
Loader : Loaders := external("LOADER", "RAM");
MPFS_ARCH := external("MPFS_ARCH", "rv64imafdc");
MPFS_ABI  := external("MPFS_ABI",  "lp64d");
--  Note: "-march=rv64imac" alone fails to assemble the startup code --
--  the E51 string is rv64imac_zicsr (RTS-POLARFIRE.md §1.1). Defaults
--  above match Hart_Class => u54 (CONTRACT.md §3.2's default); an
--  application targeting the E51 must pass
--  -XMPFS_ARCH=rv64imac_zicsr -XMPFS_ABI=lp64 explicitly (see
--  README.md, "Two knobs, not one").

package Compiler is
   Common_Required_Switches := ("-march=" & MPFS_ARCH, "-mabi=" & MPFS_ABI,
                                "-fno-tree-loop-distribute-patterns");

   for Leading_Required_Switches ("Ada") use
      Compiler'Leading_Required_Switches ("Ada") &
      Common_Required_Switches;
   for Leading_Required_Switches ("C") use
      Compiler'Leading_Required_Switches ("C") &
      Common_Required_Switches;
   for Leading_Required_Switches ("C++") use
      Compiler'Leading_Required_Switches ("C++") &
      Common_Required_Switches;
   for Leading_Required_Switches ("Asm") use
      Compiler'Leading_Required_Switches ("Asm") &
      Common_Required_Switches;
   for Leading_Required_Switches ("Asm2") use
      Compiler'Leading_Required_Switches ("Asm2") &
      Common_Required_Switches;
   for Leading_Required_Switches ("Asm_Cpp") use
      Compiler'Leading_Required_Switches ("Asm_Cpp") &
      Common_Required_Switches;
end Compiler;

package Linker is
   --  THE LINK GROUP (RTS.md A.14): embedded_mpfs must add
   --  --start-group,-lgnarl,-lgnat,-lc,-lgcc,--end-group here.
   --  light_mpfs and light_tasking_mpfs must NOT -- carrying it into
   --  those profiles is not merely unneeded, it is the one place this
   --  leaf's runtime.xml differs from theirs.
   for Required_Switches use Linker'Required_Switches &
     ("-Wl,-L${RUNTIME_DIR(Ada)}/adalib", "-nostartfiles", "-nolibc",
      "-Wl,--start-group,-lgnarl,-lgnat,-lc,-lgcc,--end-group",
      "-L${RUNTIME_DIR(ada)}/ld_user",
      "-L${RUNTIME_DIR(ada)}/ld")
     & Compiler.Common_Required_Switches;
end Linker;
